#!/bin/bash
###############################################################################
# !!!!!!!!!!!!!!! OPTIONS !!!!!!!!!!!!!!!

# General options
MIRRORING_MODE='local' # remote/local/manual/local_in_l2rt_core, remote mirrors to EIF2, local dumps data to gNB, manual enables mirroring but ABIL Master/Slave Xeon but does not capture data or disable mirroring


# Mirror BB boards
BB_SLOT_1='false' # true/false
BB_SLOT_2='false' # true/false
BB_SLOT_3='false' # true/false
BB_SLOT_5='false' # true/false
BB_SLOT_6='false' # true/false
BB_SLOT_7='false' # true/false
if [ -d "/tftpboot/slot01" ]; then
    BB_SLOT_1='true'
fi
if [ -d "/tftpboot/slot02" ]; then
    BB_SLOT_2='true'
fi
if [ -d "/tftpboot/slot03" ]; then
    BB_SLOT_3='true'
fi
if [ -d "/tftpboot/slot05" ]; then
    BB_SLOT_5='true'
fi
if [ -d "/tftpboot/slot06" ]; then
    BB_SLOT_6='true'
fi
if [ -d "/tftpboot/slot07" ]; then
    BB_SLOT_7='true'
fi


# Mirrored interfaces, the less interfaces are configured for mirroring, the better are chances to not to drop packets
L2_L1_BIP='true' # true/false/l2l1/l1l2
SYSCOM_MIRRORING='false' # true/false, mirrors syscom traffic between control and baseband boards for ABILs that are mirrored
BACKHAUL_MIRRORING='false' # true/false, S1/X2 in Classical deployment, F1-U in Cloud deployment, works only in ASIK
L2HI_MIRRORING='false' # true/false, traffic to/from L2-HI, only in ASIK
L2RT_MIRRORING='false' # true/false, traffic to/from L2-RT
CPRT_MIRRORING='false' # true/false, traffic to/from CP-RT, only in ASIK

# Local mode options
FILTERING='off' # on/off, on enables capture filter, give filter in FILTER argument, for syntax see https://www.tcpdump.org/manpages/tcpdump.1.html
FILTER='ether[0x18:2]!=0xe101 and ether[0x18:2]!=0x131 and ether[0x18:2]!=0xe206 and ether[0x18:2]!=0xe105 and ether[0x18:2]!=0xe111 and ether[0x18:2]!=0xe229' # ABIL
#FILTER='ether[0x1c:2]!=0xe101 and ether[0x1c:2]!=0x131 and ether[0x1c:2]!=0xe206 and ether[0x1c:2]!=0xe105 and ether[0x1c:2]!=0xe111 and ether[0x1c:2]!=0xe229' # ABIO
USE_GULP='false' # true/false, use gulp engine for capturing instead of tcpdump, provides better performance, works with ASIK+ABIL
CAPTURING_TIME_SECONDS=3000 # in seconds/special value 'infinite' or 0 keeps capture rolling
NUMBER_OF_FILES=10 # number of files created, tcpdump -W
FILE_SIZE_MBYTES=100 # size of file create, tcpdump -C
SNAPLEN='262144' # Snarf snaplen bytes of data from each packet rather than the default of 262144 bytes.
CAPTURING_INTERFACE="default"

# Triggering options
WAIT_FOR_JOURNAL_EVENT="off" # off/<string>, polling L1 journal to stop capturing when XXX string is logged to journal
BB_NODE_FOR_TRIGGER="1:2"

# Debug options
XTRACE='off' # on/off

###############################################################################

# FILTER message IDs
# By default, periodic control messages are filtered out
# https://gitlabe1.ext.net.nokia.com/high-five/3gpp-interfaces-5g-layer-1/-/wikis/5G-3GPP-Interface-Message-IDs
# Some common message IDs
# 5G19A
#   - PatternConfigReq 0x12b
#   - SlotTypeReq 0x122
#   - PrachReceiveReq 0x233
#   - CsiRsSendReq 0x12a
#   - SsBlocSendReq 0x127
#   - pdschPayloadTbSendReq 0x108
#   - puschReceiveRespLo 0x23a
#  Changes in 5G19B
#   - PrachReceiveReq 0xE206
#   - CsiRsSendReq 0x131
#  Changes in 5G20A
#   - PatternConfigReq 0xe101
#  5G20B
#   - SsBlocSendReq 0xe105
#  CB007786
#   - EmptySendReq 0xe111
#   - EmptyReceiveReq 0xe229
#
#




